const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  const body = (item.json && item.json.body) || {};
  let b64 = String(body.pdf_base64 || '').trim();
  if (!b64) {
    throw new Error('No file was uploaded. Send the PDF as multipart/form-data (field "data", type File), or as JSON with "pdf_base64" or "pdf_url".');
  }
  b64 = b64.replace(/^data:[^;,]*;base64,/i, '').replace(/\s+/g, '');
  const decoded = Buffer.from(b64, 'base64');
  if (decoded.slice(0, 5).toString('latin1') !== '%PDF-') {
    throw new Error('pdf_base64 does not decode to a PDF. Encode the raw PDF file bytes as standard base64.');
  }
  const bin = await this.helpers.prepareBinaryData(decoded, String(body.file_name || 'file.pdf'), 'application/pdf');
  return [{ json: { pdf_base64: decoded.toString('base64'), file_name: String(body.file_name || ''), mime_type: 'application/pdf' }, binary: { data: bin } }];
}
const key = binaryKeys.includes('data') ? 'data' : binaryKeys[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
if (buffer.slice(0, 5).toString('latin1') !== '%PDF-') {
  throw new Error('The received file is not a PDF. For uploads, send multipart/form-data with the field type set to File. For pdf_url, make sure the link is public and points directly to a PDF.');
}
let replacementChars = 0;
for (let i = 0; i + 2 < Math.min(buffer.length, 200000); i++) {
  if (buffer[i] === 0xEF && buffer[i + 1] === 0xBF && buffer[i + 2] === 0xBD) replacementChars++;
}
if (replacementChars > 50) {
  throw new Error('The PDF arrived corrupted (binary bytes were converted to text by the sender). In Postman use the Desktop Agent and set the form-data key type to File, or use curl -F "data=@file.pdf;type=application/pdf".');
}
return [{ json: { pdf_base64: buffer.toString('base64'), file_name: item.binary[key].fileName || '', mime_type: item.binary[key].mimeType || 'application/pdf' }, binary: { data: item.binary[key] } }];

