const cand = $json.candidates?.[0] || {};
const finishReason = cand.finishReason || '';
let raw = (cand.content?.parts || []).map(p => p.text || '').join('').trim();

if (!raw) {
  throw new Error('Gemini رجّع رد فاضي (finishReason: ' + finishReason + ').' +
    (finishReason === 'RECITATION' ? ' جرّب إعادة التشغيل أو قسّم الـ PDF.' : ''));
}

// أول سطر: CLASS: <كلمة>، وبعده النص
let classification = 'غير_محدد';
let text = raw;
const m = raw.match(/^\s*CLASS:\s*([^\n\r]+)/i);
if (m) {
  classification = m[1].trim().replace(/\s+/g, '_');
  text = raw.slice(m[0].length).trim();
}

if (text.length < 20) {
  throw new Error('لم يتم استخراج نص كافٍ. classification: ' + classification + ' | finishReason: ' + finishReason);
}

return [{
  json: {
    text,
    classification,
    truncated: finishReason === 'MAX_TOKENS',
    finish_reason: finishReason
  }
}];

const input = $input.first()?.json || {};
let text = String(input.text || '').replace(/\s+/g, ' ').trim();
const classification = input.classification || 'unknown';
let fileName = '';
try { fileName = String($('PDF to Base64').first().json.file_name || ''); } catch (e) { fileName = ''; }
let title = fileName.replace(/\.pdf$/i, '').trim();
if (!title) title = text.slice(0, 80).trim() || ('مستند ' + classification);

const documentId = 'doc-' + Date.now();
const chunkSize = 3500, overlap = 350, step = chunkSize - overlap;
const output = [];

for (let start = 0, index = 0; start < text.length; start += step, index++) {
  const piece = text.slice(start, start + chunkSize).trim();
  if (piece) {
    output.push({
      json: {
        document_id: documentId,
        chunk_id: documentId + '-' + index,
        chunk_index: index,
        document_type: classification,
        title: title,
        text: piece,
        truncated: !!input.truncated
      }
    });
  }
}
return output;

