const text = String($json.text || '').trim();
const head = text.slice(0, 3000);
let classification = 'غير_محدد';
if (/باسم الشعب|حكمت المحكمة|منطوق الحكم|أسباب الحكم/.test(head)) classification = 'حكم_قضائي';
else if (/الطرف الأول|الطرف الثاني|حُرر هذا العقد|تحرر هذا العقد|عقد\s/.test(head)) classification = 'عقد';
else if (/اللائحة التنفيذية|لائحة\s/.test(head)) classification = 'لائحة';
else if (/قانون رقم|المادة\s*\(?\d|مادة\s*\(?\d/.test(head)) classification = 'قانون';
return [{ json: { text, classification, truncated: false } }];
